INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.d', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS', 'd', 'narrate ways of applying safety around water points at home', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.e', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS', 'e', 'appreciate water safety at home for life skills', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'CREA.G1.CREATI.JUMPING', 'creative_activities', 1, 'Name ways of jumping and how to jump safely', ARRAY['CREA.G1.CREATI.JUMPING.a']::text[], 'The child names ways of jumping (for height, for distance, forward, backward, to the right, to the left, over a rope or a line), says a jump takes off and lands on two feet with bent knees, and names one safety rule (land softly, jump on soft ground, leave space between children). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) improvise objects to be used for jumping; c) jump in different ways for coordination; d) sing songs while jumping for fun.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT', 'CREA.G1.CREATI.RHYTHM', 'creative_activities', 1, 'Identify things that keep a steady beat', ARRAY['CREA.G1.CREATI.RHYTHM.a']::text[], 'The child names things that keep a steady pulse (a clock ticking, walking feet, a heartbeat, a drum played evenly), tells a steady beat from sounds that come at uneven times (rain, people talking), and says a steady beat goes on evenly like walking. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) play a steady beat on a percussion instrument while singing.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'CREA.G1.CREATI.RHYTHM', 'creative_activities', 1, 'Name the body percussion sounds', ARRAY['CREA.G1.CREATI.RHYTHM.c']::text[], 'The child names the body percussion sounds (clapping hands, tapping knees or the chest, snapping fingers, stamping feet) and says which body parts make each, and that body percussion can accompany a song by keeping its beat. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: c) create a rhythmic accompaniment to a song using body percussion.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES', 'CREA.G1.CREATI.DRAWING', 'creative_activities', 1, 'Identify kinds of lines and their directions', ARRAY['CREA.G1.CREATI.DRAWING.a']::text[], 'The child names straight, wavy, zigzag and curved lines, says the direction of a straight line (standing up: vertical; lying down: horizontal; slanting: diagonal), and finds each kind of line in objects around them (a door edge, a road, a snake, a fence). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) draw lines in different directions; c) draw patterns using lines in different directions.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH', 'CREA.G1.CREATI.STRETCHING', 'creative_activities', 1, 'Name the body parts and directions of stretching', ARRAY['CREA.G1.CREATI.STRETCHING.a']::text[], 'The child names the body parts that stretch (arms, legs, back, neck, fingers), the directions of a stretch (upwards, forward, backwards, sideways) and the positions (standing, sitting, kneeling, lying), and says a stretch is slow and held without bouncing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) perform stretching in different directions for flexibility.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'CREA.G1.CREATI.PAINTING_AND_COLOURING', 'creative_activities', 1, 'Identify materials and tools for painting and colouring', ARRAY['CREA.G1.CREATI.PAINTING_AND_COLOURING.a']::text[], 'The child sorts what is used up (materials: paper, fabric, paints, crayons) from what helps them work (tools: brushes, sponges, a palette), names each, and names the colours of things around them to colour them as they look (green leaves, a blue sky, brown soil). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) colour a picture to immitate the environment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'CREA.G1.CREATI.PAINTING_AND_COLOURING', 'creative_activities', 1, 'Say how to paint with a brush, fingers and a sponge', ARRAY['CREA.G1.CREATI.PAINTING_AND_COLOURING.c']::text[], 'The child says how each way of painting is done (a brush: dip the tip and stroke; fingers: dip one finger and dab or drag; a sponge: dip, press and lift) and which mark each makes (lines, dots, soft patches), and says hands and tools are washed afterwards. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: c) paint shapes using a brush; d) paint using fingers on a surface; e) paint using a sponge on a surface.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'CREA.G1.CREATI.MELODY', 'creative_activities', 1, 'Tell melodic from non-melodic sounds', ARRAY['CREA.G1.CREATI.MELODY.a']::text[], 'The child says a melodic sound has a tune that can be sung or hummed (a song, a flute, a bird singing) and a non-melodic sound has no tune (a door banging, clapping, a drum, a hammer), and sorts sounds into the two. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'CREA.G1.CREATI.MELODY', 'creative_activities', 1, 'Recognise like and unlike passages in short melodies', ARRAY['CREA.G1.CREATI.MELODY.b']::text[], 'The child hears two short parts of a melody and says if they are like (the same tune) or unlike (a different tune), and listens to the tune, not only the words. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO', 'CREA.G1.CREATI.MELODY', 'creative_activities', 1, 'Say how to echo a melodic pattern', ARRAY['CREA.G1.CREATI.MELODY.c']::text[], 'The child says to echo is to listen first and then sing or hum back exactly the same short tune, the same speed and the same loudness, and waits until the leader has finished before echoing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: c) echo simple melodic patterns by singing or humming for aural skill development.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'CREA.G1.CREATI.PATTERN_MAKING', 'creative_activities', 1, 'Recognise and continue patterns of letters and numerals', ARRAY['CREA.G1.CREATI.PATTERN_MAKING.a']::text[], 'The child says a pattern is something that repeats in the same order, finds the part that repeats in a pattern of letters (a b a b, or o x o x) or numerals (1 2 1 2, or 3 3 4 3 3 4) and says what comes next. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.1.1), never as a phone question: b) create patterns using letters; c) make a pattern using numerals.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY', 'creative_activities', 1, 'Identify props and parts of a Kenyan singing game', ARRAY['CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.a']::text[], 'The child names props used in a singing game from a Kenyan community (a stick, a shaker, a scarf or leso, a basket, leaves, a fly whisk), says what each is used for in the game, and names the parts of a singing game: the song, the game actions, the formation (a ring or a line), the props, safety and good behaviour. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) improvise a simple prop for use in performing a singing game; c) perform singing games drawn from local cultures in Kenyan for enjoyment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'CREA.G1.PERFOR.THROWING_AND_CATCHING', 'creative_activities', 1, 'Identify materials to improvise a ball', ARRAY['CREA.G1.PERFOR.THROWING_AND_CATCHING.a']::text[], 'The child names locally available materials for making a ball (old paper, polythene bags, old cloth or socks, banana fibre, string to tie it) and says a good ball is round, firm and soft enough not to hurt. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) improvise a ball from locally available materials.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'CREA.G1.PERFOR.THROWING_AND_CATCHING', 'creative_activities', 1, 'Say how to throw and catch a ball', ARRAY['CREA.G1.PERFOR.THROWING_AND_CATCHING.c']::text[], 'The child says how to throw (look at the partner, swing the arm and let go towards them, gently and underarm for a short throw) and how to catch (eyes on the ball, hands ready like a cup, pull the ball in to the chest). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: c) perform throwing and catching activities for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'CREA.G1.PERFOR.PAPER_CRAFT', 'creative_activities', 1, 'Identify items made by paper craft and the pleating and folding techniques', ARRAY['CREA.G1.PERFOR.PAPER_CRAFT.a']::text[], 'The child names items made by paper craft (a fan, a paper boat, a hat, a flower, a paper chain), says pleating is folding forward and back again and again like a fan, and folding is creasing paper over to make a shape such as a boat or a hat. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) make paper items using the pleating technique; c) make paper items using the folding technique; d) play using the paper items for enjoyment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE', 'creative_activities', 1, 'Identify the log roll and the T-balance', ARRAY['CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.a']::text[], 'The child says in a log roll the body lies stretched straight like a log with arms above the head and rolls sideways along the mat, and in a T-balance the child stands on one leg, leans forward and lifts the other leg straight back with arms out so the body makes a T; names the markers that show where to start. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) make markers for use during log rolls and T-balance performance; c) perform a log roll for coordination; d) perform the T-balance for flexibility.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.SONGS.ACTION_SONG', 'CREA.G1.PERFOR.SONGS', 'creative_activities', 1, 'Describe the message of an action song and how to perform it', ARRAY['CREA.G1.PERFOR.SONGS.a']::text[], 'The child says what an action song they know is about (brushing teeth, washing hands, animals, parts of the body) and what it tells us to do, and says the performance techniques: the right tune and rhythm, clear words, actions and gestures that show the words, a face that shows the mood. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) sing action songs in unison applying performance techniques.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.MODELLING.PINCH', 'CREA.G1.PERFOR.MODELLING', 'creative_activities', 1, 'Identify items made by pinching and the materials and tools of modelling', ARRAY['CREA.G1.PERFOR.MODELLING.a', 'CREA.G1.PERFOR.MODELLING.b']::text[], 'The child names items made by the pinch method (small pots, cups, bowls) and how it is done (roll a ball, push the thumb into the middle, pinch the sides round and round), and names modelling materials (clay, plasticine, dough, soil mixed with water) and tools (a board, a stick for marking, water). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: c) model items using the pinch method.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR', 'creative_activities', 1, 'Identify percussion instruments and how they are played', ARRAY['CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.a']::text[], 'The child names percussion instruments from Kenyan communities (drums, shakers, jingles, rattles), says they are played by hitting, shaking or scraping, and which way suits each (a drum: hit; a shaker: shake; a scraper: scrape). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.2.1), never as a phone question: b) improvise a percussion musical instrument using locally available materials; c) play a percussion musical instrument for enjoyment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'CREA.G1.APPREC.MUSICAL_SOUNDS', 'creative_activities', 1, 'Identify sounds in the local environment and their sources', ARRAY['CREA.G1.APPREC.MUSICAL_SOUNDS.a']::text[], 'The child names the source of a sound in the local environment (birds, animals, people, objects such as a car, a bell, a hammer, rain on the roof) and sorts sounds by their source. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.3.1), never as a phone question: c) respond to sounds in the environment for self-expression.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'CREA.G1.APPREC.MUSICAL_SOUNDS', 'creative_activities', 1, 'Describe volume, speed and pitch in a song', ARRAY['CREA.G1.APPREC.MUSICAL_SOUNDS.b']::text[], 'The child tells loud from soft (volume), fast from slow (speed) and high from low (pitch) in a song, and does not mix them up (a loud sound is not always high, a fast song is not always loud). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'CREA.G1.APPREC.MUSICAL_SOUNDS', 'creative_activities', 1, 'Describe the mood of a song', ARRAY['CREA.G1.APPREC.MUSICAL_SOUNDS.d']::text[], 'The child says if a song sounds happy, sad, calm or exciting, and gives a reason from the music (fast and bouncy, slow and soft) or the words. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 1, 'Recognise water points at home and their dangers', ARRAY['CREA.G1.APPREC.WATER_SAFETY_AWARENESS.a', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.b']::text[], 'The child names water points around the home (a tap, a water tank, a drum or jerrican of water, a basin or bucket, a well, a pond nearby) and the dangers each holds (drowning, even in a bucket for a small child; slipping on a wet floor; falling into a well). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G1.RUBRIC.3.1), never as a phone question: c) make a montage of water points around the home environment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 1, 'Say how to keep safe around water points at home', ARRAY['CREA.G1.APPREC.WATER_SAFETY_AWARENESS.d']::text[], 'The child names ways to keep safe around water at home (never play in or near water without an adult, keep buckets, drums and wells covered, empty basins after use, walk on wet floors, call an adult if a little child goes near water). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'CREA.PP2.READINESS.MOVE_BASIC', 'skill', 'essential', 'Jumping on two feet in play (pre-primary) comes before naming ways and directions of jumping. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH', 'skill', 'helpful', 'Comparing longer and shorter (Grade 1 Maths) is used to tell a jump for distance. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT', 'CREA.PP2.READINESS.CLAP_ALONG', 'skill', 'essential', 'Clapping along with a song (pre-primary) comes before naming what keeps a steady beat. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT', 'CREA.PP2.READINESS.LISTEN_SOUNDS', 'skill', 'essential', 'Naming familiar sounds (pre-primary) is needed to say which keep a steady beat. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'CREA.PP2.READINESS.BODY_PARTS', 'skill', 'essential', 'Naming body parts (pre-primary) is needed to say which part makes each sound. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'CREA.G1.CREATI.RHYTHM.BEAT', 'skill', 'essential', 'Feeling a steady beat comes before keeping it with body percussion. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES', 'MATH.G1.GEOMET.LINES.IDENTIFY_LINES', 'skill', 'essential', 'Telling straight from curved lines (Grade 1 Maths) is the start of naming wavy and zigzag lines. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES', 'CREA.PP2.READINESS.HOLD_CRAYON', 'skill', 'essential', 'Holding a crayon and making marks (pre-primary) comes before drawing lines in named directions. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH', 'CREA.PP2.READINESS.BODY_PARTS', 'skill', 'essential', 'Naming the main body parts (pre-primary) comes before naming the parts that stretch. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH', 'CREA.PP2.READINESS.MOVE_BASIC', 'skill', 'essential', 'Moving and standing still on request (pre-primary) is needed to hold a stretch. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'CREA.PP2.READINESS.COLOUR_NAMES', 'skill', 'essential', 'Naming the basic colours (pre-primary) is needed to colour things as they look. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'CREA.PP2.READINESS.HOLD_CRAYON', 'skill', 'essential', 'Holding a crayon or brush (pre-primary) comes before naming materials and tools. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'skill', 'essential', 'Knowing the tools comes before saying how each is used. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'CREA.PP2.READINESS.HOLD_CRAYON', 'skill', 'essential', 'Making marks with a crayon or brush (pre-primary) comes before painting shapes. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'CREA.PP2.READINESS.LISTEN_SOUNDS', 'skill', 'essential', 'Naming familiar sounds (pre-primary) comes before sorting them as melodic or not. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'CREA.PP2.READINESS.SING_RHYMES', 'skill', 'essential', 'Singing songs (pre-primary) gives the child the feel of a tune. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'skill', 'essential', 'Knowing what a tune is comes before telling two tunes apart. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'MATH.PP2.READINESS.SORT_ONE_ATTRIBUTE', 'skill', 'helpful', 'Sorting by one attribute (pre-primary Maths) is the same thinking as sorting tunes into same and different. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'skill', 'essential', 'Hearing when two tunes are the same is how an echo is checked. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO', 'CREA.PP2.READINESS.SING_RHYMES', 'skill', 'essential', 'Singing simple songs (pre-primary) comes before singing back a tune. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'MATH.PP2.READINESS.COPY_AB_PATTERN', 'skill', 'essential', 'Copying a two-part pattern (pre-primary Maths) comes before patterns of letters and numerals. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
