INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'MATH.PP2.READINESS.SIZE_WORDS', 'skill', 'essential', 'Using opposite words such as big and small (pre-primary Maths) prepares loud and soft, fast and slow, high and low. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
