INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'ENVI.G1.RESOUR.WATER.a', 'outcome', 'essential', 'Sources of water in the immediate environment (Grade 1 Environmental Activities) name the water points at home. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'CREA.PP2.READINESS.STAY_WITH_ADULT', 'skill', 'essential', 'Knowing to stay near a trusted adult (pre-primary) is the first safety idea around water. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'skill', 'essential', 'Knowing the water points and their dangers comes before naming how to keep safe. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'ENVI.G1.SOCIAL.OUR_HOME.b', 'outcome', 'essential', 'Common accidents at home (Grade 1 Environmental Activities) include accidents with water. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS.M_CAC1_JU_ONE_FOOT', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'Calls hopping on one foot a jump.', '{"question":"Is hopping on one foot the same as jumping on two feet?","wrong_answer":"yes","correct_answer":"no, a jump uses two feet"}'::jsonb, 'Young children use "jump" for every bounce.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Jump on two feet, then hop on one, and look at the feet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS.M_CAC1_JU_STIFF_LEGS', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'Lands with straight, stiff legs.', '{"question":"How should your knees be when you land from a jump?","wrong_answer":"straight and stiff","correct_answer":"bent, so you land softly"}'::jsonb, 'The child does not feel the jolt as a danger.', 'Offer "straight and stiff" next to the right answer and ask the question again in a new context.', 'Land like a cat, quietly, with bent knees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS.M_CAC1_JU_HEIGHT_DIST', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'Mixes up jumping for height and jumping for distance.', '{"question":"You jump as far forward as you can. Is that a jump for height or for distance?","wrong_answer":"for height","correct_answer":"for distance"}'::jsonb, 'The child has not linked the words to the movement.', 'Offer "for height" next to the right answer and ask the question again in a new context.', 'Jump up to touch a leaf (height), then jump to a line far away (distance).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.JUMPING.JUMP_WAYS.M_CAC1_JU_CLOSE', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'Jumps very close to other children.', '{"question":"Where should you stand when many children jump?","wrong_answer":"close to my friends","correct_answer":"with space around me"}'::jsonb, 'The child likes to stay near friends.', 'Offer "close to my friends" next to the right answer and ask the question again in a new context.', 'Stretch arms out: no one should be inside your space.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT.M_CAC1_BT_RAIN', 'CREA.G1.CREATI.RHYTHM.BEAT', 'Says rain on the roof keeps a steady beat.', '{"question":"Does rain on the roof keep a steady beat?","wrong_answer":"yes","correct_answer":"no, the drops come at uneven times"}'::jsonb, 'Rain makes a repeated sound, so the child hears it as a beat.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Clap with a clock tick, then try to clap with the rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT.M_CAC1_BT_FASTER', 'CREA.G1.CREATI.RHYTHM.BEAT', 'Gets faster and faster while keeping a beat.', '{"question":"When you keep a steady beat, does it get faster?","wrong_answer":"yes, faster and faster","correct_answer":"no, it stays even"}'::jsonb, 'Excitement makes the child speed up.', 'Offer "yes, faster and faster" next to the right answer and ask the question again in a new context.', 'Walk to the drum: do your feet speed up?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT.M_CAC1_BT_TALK', 'CREA.G1.CREATI.RHYTHM.BEAT', 'Says people talking keep a steady beat.', '{"question":"Which keeps a steady beat: a ticking clock or people talking?","wrong_answer":"people talking","correct_answer":"a ticking clock"}'::jsonb, 'Talking is a sound the child hears all the time.', 'Offer "people talking" next to the right answer and ask the question again in a new context.', 'Clap with talking, then with a clock.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BEAT.M_CAC1_BT_LOUD', 'CREA.G1.CREATI.RHYTHM.BEAT', 'Thinks a steady beat must be loud.', '{"question":"Can a soft sound keep a steady beat?","wrong_answer":"no, it must be loud","correct_answer":"yes"}'::jsonb, 'Drums are loud, so the child links beat with loudness.', 'Offer "no, it must be loud" next to the right answer and ask the question again in a new context.', 'Tap a steady beat softly with one finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION.M_CAC1_BP_SNAP_CLAP', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'Calls snapping fingers clapping.', '{"question":"You rub your thumb and finger to make a click. What is that?","wrong_answer":"clapping","correct_answer":"snapping"}'::jsonb, 'Both make a short sound with the hands.', 'Offer "clapping" next to the right answer and ask the question again in a new context.', 'Clap, then snap, and look at the hands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION.M_CAC1_BP_STAMP_HANDS', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'Says stamping is done with the hands.', '{"question":"Which body part do you stamp with?","wrong_answer":"hands","correct_answer":"feet"}'::jsonb, 'The child mixes the new words.', 'Offer "hands" next to the right answer and ask the question again in a new context.', 'Stamp your feet while saying "stamp".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION.M_CAC1_BP_INSTRUMENT', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'Thinks you need an instrument to play percussion.', '{"question":"Can you play percussion with only your body?","wrong_answer":"no, you need a drum","correct_answer":"yes, by clapping, tapping, snapping and stamping"}'::jsonb, 'Percussion was shown with drums.', 'Offer "no, you need a drum" next to the right answer and ask the question again in a new context.', 'Play a song with claps and stamps only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION.M_CAC1_BP_OFF_BEAT', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'Claps whenever they like during a song.', '{"question":"When you clap along to a song, when do you clap?","wrong_answer":"whenever I want","correct_answer":"on the beat, evenly with the song"}'::jsonb, 'The child claps for fun, not in time.', 'Offer "whenever I want" next to the right answer and ask the question again in a new context.', 'Walk and clap together with the song.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES.M_CAC1_LN_WAVY_ZIGZAG', 'CREA.G1.CREATI.DRAWING.LINES', 'Calls a wavy line a zigzag.', '{"question":"A line goes up and down smoothly like water. Is it a zigzag?","wrong_answer":"yes","correct_answer":"no, it is wavy"}'::jsonb, 'Both lines go up and down.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Draw both: the zigzag has sharp points, the wavy line is smooth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES.M_CAC1_LN_VERTICAL', 'CREA.G1.CREATI.DRAWING.LINES', 'Calls a line lying down vertical.', '{"question":"A line lies flat like the floor. What is it?","wrong_answer":"vertical","correct_answer":"horizontal"}'::jsonb, 'The new words are easily swapped.', 'Offer "vertical" next to the right answer and ask the question again in a new context.', 'Stand up straight (vertical), then lie down flat (horizontal).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES.M_CAC1_LN_DIAGONAL', 'CREA.G1.CREATI.DRAWING.LINES', 'Calls a slanting line straight up.', '{"question":"A line slants like a ladder against a wall. What is it?","wrong_answer":"vertical","correct_answer":"diagonal"}'::jsonb, 'It goes upwards, so the child calls it standing up.', 'Offer "vertical" next to the right answer and ask the question again in a new context.', 'Lean a ruler against a box and compare with a ruler standing up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.DRAWING.LINES.M_CAC1_LN_CURVED_STRAIGHT', 'CREA.G1.CREATI.DRAWING.LINES', 'Says a bent stick drawing is a straight line because it is a line.', '{"question":"Is the edge of a ball a straight line or a curved line?","wrong_answer":"straight","correct_answer":"curved"}'::jsonb, 'All lines seem straight to the child.', 'Offer "straight" next to the right answer and ask the question again in a new context.', 'Run a finger round a ball and along a ruler.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH.M_CAC1_SR_BOUNCE', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'Bounces up and down to stretch further.', '{"question":"How do you stretch your legs safely?","wrong_answer":"bounce up and down","correct_answer":"reach slowly and hold still"}'::jsonb, 'Bouncing looks like trying harder.', 'Offer "bounce up and down" next to the right answer and ask the question again in a new context.', 'Reach slowly, count to five and hold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH.M_CAC1_SR_SIDEWAYS', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'Stretches forward when asked to stretch sideways.', '{"question":"Stretch sideways. Which way do your arms go?","wrong_answer":"in front of me","correct_answer":"out to the sides"}'::jsonb, 'The word "sideways" is new.', 'Offer "in front of me" next to the right answer and ask the question again in a new context.', 'Stand between two friends and reach towards each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH.M_CAC1_SR_STANDING_ONLY', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'Thinks you can only stretch standing up.', '{"question":"Can you stretch while sitting or lying down?","wrong_answer":"no, only standing","correct_answer":"yes"}'::jsonb, 'Stretches seen at assembly are standing.', 'Offer "no, only standing" next to the right answer and ask the question again in a new context.', 'Do one stretch in each position.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.STRETCHING.STRETCH.M_CAC1_SR_HURT', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'Thinks a stretch should hurt to work.', '{"question":"Should a stretch hurt?","wrong_answer":"yes, it must hurt","correct_answer":"no; you feel a gentle pull, not pain"}'::jsonb, 'Children hear that exercise is hard.', 'Offer "yes, it must hurt" next to the right answer and ask the question again in a new context.', 'Stretch until you feel a gentle pull, then stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS.M_CAC1_PT_BRUSH_MATERIAL', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'Calls a brush a material.', '{"question":"Is a brush a tool or a material?","wrong_answer":"a material","correct_answer":"a tool"}'::jsonb, 'The child has not sorted used-up things from working things.', 'Offer "a material" next to the right answer and ask the question again in a new context.', 'Sort: what is used up (paint, paper) and what we use again (brush, sponge).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS.M_CAC1_PT_SKY_GREEN', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'Colours the sky green and the grass blue.', '{"question":"Which colour is the sky on a clear day?","wrong_answer":"green","correct_answer":"blue"}'::jsonb, 'The child picks the nearest crayon or mixes up colour names.', 'Offer "green" next to the right answer and ask the question again in a new context.', 'Go outside and name the colour of the sky and the grass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS.M_CAC1_PT_PALETTE', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'Thinks a palette is a kind of paint.', '{"question":"What is a palette?","wrong_answer":"a kind of paint","correct_answer":"a flat board or plate to hold and mix paint"}'::jsonb, 'The word is new.', 'Offer "a kind of paint" next to the right answer and ask the question again in a new context.', 'Show a palette with paint on it, or a plastic lid used as one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS.M_CAC1_PT_FABRIC', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'Thinks you can only paint on paper.', '{"question":"Can you paint on fabric?","wrong_answer":"no, only paper","correct_answer":"yes"}'::jsonb, 'Paper is the only surface used so far.', 'Offer "no, only paper" next to the right answer and ask the question again in a new context.', 'Show a painted piece of cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS.M_CAC1_PW_SPONGE_RUB', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'Rubs the sponge hard across the paper.', '{"question":"How do you paint with a sponge?","wrong_answer":"rub it hard across the paper","correct_answer":"dip it, press it down and lift it"}'::jsonb, 'Sponges are used to wash and scrub at home.', 'Offer "rub it hard across the paper" next to the right answer and ask the question again in a new context.', 'Press and lift a sponge to make a soft patch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS.M_CAC1_PW_WHOLE_HAND', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'Dips the whole hand into the paint for finger painting.', '{"question":"For finger painting, what do you dip?","wrong_answer":"the whole hand","correct_answer":"one finger"}'::jsonb, 'The child enjoys the feel of paint.', 'Offer "the whole hand" next to the right answer and ask the question again in a new context.', 'Dip one finger and make a row of dots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS.M_CAC1_PW_NO_WASH', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'Thinks hands do not need washing after painting.', '{"question":"What do you do after finger painting?","wrong_answer":"go to eat","correct_answer":"wash my hands"}'::jsonb, 'The child does not link paint with being unsafe to eat.', 'Offer "go to eat" next to the right answer and ask the question again in a new context.', 'Talk about why paint must not go in the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS.M_CAC1_PW_BRUSH_HARD', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'Presses the brush down so hard the bristles spread.', '{"question":"How do you hold the brush on the paper?","wrong_answer":"press it down hard","correct_answer":"stroke it gently"}'::jsonb, 'More pressure seems to give more colour.', 'Offer "press it down hard" next to the right answer and ask the question again in a new context.', 'Paint one line pressing hard and one gently.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS.M_CAC1_MS_DRUM', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'Says a drum makes a melodic sound.', '{"question":"Does a drum make a sound with a tune you can hum?","wrong_answer":"yes","correct_answer":"no, it is non-melodic"}'::jsonb, 'Drums are in music, so the child thinks they make tunes.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Hum along with a flute, then try with a drum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS.M_CAC1_MS_BIRD', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'Says a bird singing is non-melodic because it is not a person.', '{"question":"Is a bird singing a melodic sound?","wrong_answer":"no, only people sing","correct_answer":"yes, it has a tune"}'::jsonb, 'The child links tunes only with people.', 'Offer "no, only people sing" next to the right answer and ask the question again in a new context.', 'Whistle back a bird''s tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS.M_CAC1_MS_LOUD', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'Thinks loud sounds are melodic and soft ones are not.', '{"question":"A door bangs loudly. Is it melodic?","wrong_answer":"yes, it is loud","correct_answer":"no, it has no tune"}'::jsonb, 'Loudness catches the child''s attention.', 'Offer "yes, it is loud" next to the right answer and ask the question again in a new context.', 'Hum softly, then bang a desk; which has a tune?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.MELODIC_SOUNDS.M_CAC1_MS_CLAP', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'Says clapping is melodic because it is used in songs.', '{"question":"Is clapping a melodic sound?","wrong_answer":"yes","correct_answer":"no, it has no tune"}'::jsonb, 'Clapping goes with songs.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Try to clap a tune: can you make it go up and down?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE.M_CAC1_LU_WORDS', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'Says two parts are unlike because the words are different.', '{"question":"Two parts have the same tune and different words. Like or unlike?","wrong_answer":"unlike","correct_answer":"like"}'::jsonb, 'The child listens to the words.', 'Offer "unlike" next to the right answer and ask the question again in a new context.', 'Hum both parts with no words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE.M_CAC1_LU_SAME_START', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'Says two tunes are alike because they start the same.', '{"question":"Two tunes start the same but end differently. Are they like?","wrong_answer":"yes, they start the same","correct_answer":"no, they are unlike"}'::jsonb, 'The child stops listening after the start.', 'Offer "yes, they start the same" next to the right answer and ask the question again in a new context.', 'Listen to the end of each tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE.M_CAC1_LU_LOUD', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'Says a tune sung louder is unlike.', '{"question":"The same tune is sung loudly. Is it like or unlike?","wrong_answer":"unlike","correct_answer":"like"}'::jsonb, 'Loudness changes the feel.', 'Offer "unlike" next to the right answer and ask the question again in a new context.', 'Sing the tune soft and loud; are the notes the same?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.LIKE_UNLIKE.M_CAC1_LU_SINGER', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'Says a tune is unlike because a different person sings it.', '{"question":"A boy and a girl sing the same tune. Like or unlike?","wrong_answer":"unlike","correct_answer":"like"}'::jsonb, 'Different voices sound different.', 'Offer "unlike" next to the right answer and ask the question again in a new context.', 'Two children sing the same line; hum it together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO.M_CAC1_EC_TOGETHER', 'CREA.G1.CREATI.MELODY.ECHO', 'Sings along with the leader instead of after.', '{"question":"When do you sing in an echo?","wrong_answer":"at the same time as the leader","correct_answer":"after the leader has finished"}'::jsonb, 'The child is used to singing together.', 'Offer "at the same time as the leader" next to the right answer and ask the question again in a new context.', 'Hold up a hand while the leader sings; drop it to echo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO.M_CAC1_EC_NEW_TUNE', 'CREA.G1.CREATI.MELODY.ECHO', 'Sings a different tune back.', '{"question":"In an echo, what tune do you sing?","wrong_answer":"any tune","correct_answer":"exactly the same tune"}'::jsonb, 'The child likes to make up their own tune.', 'Offer "any tune" next to the right answer and ask the question again in a new context.', 'Listen, hum it in your head, then sing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO.M_CAC1_EC_LOUDER', 'CREA.G1.CREATI.MELODY.ECHO', 'Echoes much louder than the leader.', '{"question":"The leader sings softly. How do you echo?","wrong_answer":"loudly","correct_answer":"softly, the same as the leader"}'::jsonb, 'The child thinks louder is better.', 'Offer "loudly" next to the right answer and ask the question again in a new context.', 'Play an echo game in a quiet voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.MELODY.ECHO.M_CAC1_EC_FASTER', 'CREA.G1.CREATI.MELODY.ECHO', 'Rushes the echo faster than the leader.', '{"question":"Should an echo be faster than the leader?","wrong_answer":"yes","correct_answer":"no, the same speed"}'::jsonb, 'The child hurries to finish.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Echo while the teacher taps the speed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS.M_CAC1_PM_COUNT_ON', 'CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'Counts on instead of repeating: says 3 after 1 2 1 2.', '{"question":"1 2 1 2 1 2. What comes next?","wrong_answer":"3","correct_answer":"1"}'::jsonb, 'Numbers usually go on counting, so the child counts on.', 'Offer "3" next to the right answer and ask the question again in a new context.', 'Say the pattern aloud and clap on each 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS.M_CAC1_PM_LAST_AGAIN', 'CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'Repeats the last item.', '{"question":"a b a b a. What comes next?","wrong_answer":"a","correct_answer":"b"}'::jsonb, 'The child copies what was seen last.', 'Offer "a" next to the right answer and ask the question again in a new context.', 'Point and say: a b, a b, a...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS.M_CAC1_PM_UNIT_THREE', 'CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'Misses a pattern of three, treating it as two.', '{"question":"3 3 4 3 3 4 3 3. What comes next?","wrong_answer":"3","correct_answer":"4"}'::jsonb, 'The child expects every pattern to swap one by one.', 'Offer "3" next to the right answer and ask the question again in a new context.', 'Put a ring round each repeating part: 3 3 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS.M_CAC1_PM_NO_ORDER', 'CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'Thinks any row of letters is a pattern.', '{"question":"Is \"a m z k\" a pattern?","wrong_answer":"yes","correct_answer":"no, nothing repeats"}'::jsonb, 'Any row seems like a pattern to the child.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Look for a part that comes again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES.M_CAC1_KG_PROP_COSTUME', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'Calls the clothes the players wear props.', '{"question":"A girl holds a shaker in a singing game. Is the shaker a prop?","wrong_answer":"no, props are clothes","correct_answer":"yes, a prop is something held or used in the game"}'::jsonb, 'The child has not learnt the word "prop".', 'Offer "no, props are clothes" next to the right answer and ask the question again in a new context.', 'Hold up a shaker and a hat: which do you hold and use?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES.M_CAC1_KG_BUY', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'Thinks props must be bought.', '{"question":"Can you make a prop for a singing game?","wrong_answer":"no, you must buy it","correct_answer":"yes, from local materials like a bottle and seeds"}'::jsonb, 'Toys and props in shops are bought.', 'Offer "no, you must buy it" next to the right answer and ask the question again in a new context.', 'Make a shaker from a bottle and seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES.M_CAC1_KG_NO_SONG', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'Stops singing while doing the actions.', '{"question":"In a singing game, do you keep singing while you play?","wrong_answer":"no, only play","correct_answer":"yes, sing and play together"}'::jsonb, 'Doing two things at once is hard.', 'Offer "no, only play" next to the right answer and ask the question again in a new context.', 'Practise the song with small steps first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES.M_CAC1_KG_PUSH', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'Pushes to the front to get a turn.', '{"question":"In a singing game, how do you get your turn?","wrong_answer":"push to the front","correct_answer":"wait for my turn"}'::jsonb, 'The child is eager to play.', 'Offer "push to the front" next to the right answer and ask the question again in a new context.', 'Play the game and praise waiting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS.M_CAC1_BM_STONE', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'Names stones as a material for a ball.', '{"question":"Which can you use to make a ball?","wrong_answer":"stones","correct_answer":"old paper or polythene bags"}'::jsonb, 'Stones are round, so the child thinks of them.', 'Offer "stones" next to the right answer and ask the question again in a new context.', 'Feel a stone and a paper ball: which is safe to catch?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS.M_CAC1_BM_NO_TIE', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'Forgets to tie the ball, so it falls apart.', '{"question":"What do you do after rolling paper into a ball?","wrong_answer":"nothing","correct_answer":"tie it with string"}'::jsonb, 'The ball looks finished once rolled.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Throw an untied ball: it opens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS.M_CAC1_BM_FLAT', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'Makes a flat ball.', '{"question":"What shape should your ball be?","wrong_answer":"flat","correct_answer":"round"}'::jsonb, 'The child squashes the paper flat.', 'Offer "flat" next to the right answer and ask the question again in a new context.', 'Roll the paper between your hands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS.M_CAC1_BM_HARD', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'Makes the ball as hard as possible.', '{"question":"Should your ball be very hard or firm but soft?","wrong_answer":"very hard","correct_answer":"firm but soft"}'::jsonb, 'Hard seems strong to the child.', 'Offer "very hard" next to the right answer and ask the question again in a new context.', 'Catch a hard ball and a soft ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH.M_CAC1_TC_EYES_CLOSED', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'Closes the eyes or turns away when the ball comes.', '{"question":"When a ball comes to you, where do you look?","wrong_answer":"I close my eyes","correct_answer":"at the ball"}'::jsonb, 'The child is afraid of being hit.', 'Offer "I close my eyes" next to the right answer and ask the question again in a new context.', 'Use a soft ball and count as it comes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH.M_CAC1_TC_FLAT_HANDS', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'Holds the hands flat and stiff to catch.', '{"question":"How do you hold your hands to catch?","wrong_answer":"flat and stiff","correct_answer":"ready like a cup"}'::jsonb, 'The child stretches the hands out straight.', 'Offer "flat and stiff" next to the right answer and ask the question again in a new context.', 'Make a cup with your hands and catch a bean bag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH.M_CAC1_TC_HARD_THROW', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'Throws as hard as possible to a near partner.', '{"question":"Your partner is close. How do you throw?","wrong_answer":"as hard as I can","correct_answer":"gently, underarm"}'::jsonb, 'Throwing hard feels strong.', 'Offer "as hard as I can" next to the right answer and ask the question again in a new context.', 'Throw gently underarm to a partner two steps away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH.M_CAC1_TC_LOOK_AWAY', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'Throws without looking at the partner.', '{"question":"Before you throw, where do you look?","wrong_answer":"anywhere","correct_answer":"at my partner"}'::jsonb, 'The child looks at the ball in their hand.', 'Offer "anywhere" next to the right answer and ask the question again in a new context.', 'Say your partner''s name and look at them, then throw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS.M_CAC1_PA_PLEAT_ROLL', 'CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'Rolls the paper when asked to pleat it.', '{"question":"How do you pleat paper?","wrong_answer":"roll it into a tube","correct_answer":"fold it forward and back again and again"}'::jsonb, 'Rolling is the paper skill the child knows.', 'Offer "roll it into a tube" next to the right answer and ask the question again in a new context.', 'Make a paper fan by folding forward and back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS.M_CAC1_PA_CREASE', 'CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'Does not press the folds, so the shape opens.', '{"question":"After you fold paper, what do you do?","wrong_answer":"nothing","correct_answer":"press the fold flat with a finger"}'::jsonb, 'The child thinks the fold will stay by itself.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Fold without pressing, then with pressing, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS.M_CAC1_PA_TEAR', 'CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'Thinks paper craft means tearing paper.', '{"question":"Is a paper boat made by tearing or by folding?","wrong_answer":"by tearing","correct_answer":"by folding"}'::jsonb, 'Tearing is a paper activity done before.', 'Offer "by tearing" next to the right answer and ask the question again in a new context.', 'Make a boat by folding only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS.M_CAC1_PA_FAN_FOLD', 'CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'Calls a folded boat pleated.', '{"question":"A fan is made by pleating. Is a paper boat made by pleating?","wrong_answer":"yes","correct_answer":"no, by folding"}'::jsonb, 'All folding seems the same.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Put a fan and a boat side by side and look at the folds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T.M_CAC1_LR_CURLED', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'Rolls curled up when asked for a log roll.', '{"question":"In a log roll, is your body straight or curled?","wrong_answer":"curled up","correct_answer":"straight like a log"}'::jsonb, 'Children roll curled up in play.', 'Offer "curled up" next to the right answer and ask the question again in a new context.', 'Lie straight like a log and roll.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T.M_CAC1_LR_FORWARD', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'Thinks a log roll goes forward over the head.', '{"question":"Which way does a log roll go?","wrong_answer":"forward over the head","correct_answer":"sideways along the mat"}'::jsonb, 'The child has seen forward rolls.', 'Offer "forward over the head" next to the right answer and ask the question again in a new context.', 'Roll a real log or a bottle along the floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T.M_CAC1_TB_TWO_FEET', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'Stands on two feet in a T-balance.', '{"question":"In a T-balance, how many feet are on the ground?","wrong_answer":"two","correct_answer":"one"}'::jsonb, 'The child is afraid of falling.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'Hold a wall and lift one leg back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T.M_CAC1_TB_ARMS_UP', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'Holds the arms up above the head in a T-balance.', '{"question":"In a T-balance, where are your arms?","wrong_answer":"up above my head","correct_answer":"out to the sides"}'::jsonb, 'The child copies the arms of a log roll.', 'Offer "up above my head" next to the right answer and ask the question again in a new context.', 'Make a letter T with your arms out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SONGS.ACTION_SONG.M_CAC1_AS_MESSAGE_ACTIONS', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'Describes the actions when asked for the message.', '{"question":"What is the message of a song about brushing teeth?","wrong_answer":"we move our hands up and down","correct_answer":"brush your teeth to keep them clean"}'::jsonb, 'The actions are easier to describe.', 'Offer "we move our hands up and down" next to the right answer and ask the question again in a new context.', 'Ask: what does the song want us to do every day?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SONGS.ACTION_SONG.M_CAC1_AS_RANDOM_ACTION', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'Does any action, not one that shows the words.', '{"question":"The song says \"clap your hands\". What action do you do?","wrong_answer":"jump","correct_answer":"clap"}'::jsonb, 'The child likes to move in any way.', 'Offer "jump" next to the right answer and ask the question again in a new context.', 'Do each action as you sing its words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SONGS.ACTION_SONG.M_CAC1_AS_UNISON', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'Thinks singing in unison means each child sings a different song.', '{"question":"What does singing in unison mean?","wrong_answer":"each child sings their own song","correct_answer":"everyone sings the same song together"}'::jsonb, 'The word is new.', 'Offer "each child sings their own song" next to the right answer and ask the question again in a new context.', 'Sing together; then each child sings alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.SONGS.ACTION_SONG.M_CAC1_AS_SHOUT', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'Shouts the song to sing it well.', '{"question":"How do you sing an action song well?","wrong_answer":"shout it loudly","correct_answer":"sing the tune with clear words"}'::jsonb, 'Loud voices are noticed most.', 'Offer "shout it loudly" next to the right answer and ask the question again in a new context.', 'Compare a shouted line with a clear one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.MODELLING.PINCH.M_CAC1_PI_SQUASH', 'CREA.G1.PERFOR.MODELLING.PINCH', 'Squashes the ball flat instead of pinching a hollow.', '{"question":"How do you start a pinch pot?","wrong_answer":"squash the ball flat","correct_answer":"push the thumb into the middle of the ball"}'::jsonb, 'Squashing is the first thing children do with clay.', 'Offer "squash the ball flat" next to the right answer and ask the question again in a new context.', 'Push a thumb into a ball and turn it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.MODELLING.PINCH.M_CAC1_PI_ONE_PLACE', 'CREA.G1.PERFOR.MODELLING.PINCH', 'Pinches only one side, so the wall is thin there.', '{"question":"How do you pinch the sides of the pot?","wrong_answer":"in one place","correct_answer":"round and round, turning the pot"}'::jsonb, 'The child keeps working the same spot.', 'Offer "in one place" next to the right answer and ask the question again in a new context.', 'Turn the pot a little after every pinch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.MODELLING.PINCH.M_CAC1_PI_TOOL_MATERIAL', 'CREA.G1.PERFOR.MODELLING.PINCH', 'Calls the board a modelling material.', '{"question":"Is the board a tool or a material for modelling?","wrong_answer":"a material","correct_answer":"a tool"}'::jsonb, 'The child has not sorted used-up from working things.', 'Offer "a material" next to the right answer and ask the question again in a new context.', 'Sort: what becomes the pot (clay) and what helps (board, stick).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.MODELLING.PINCH.M_CAC1_PI_DRY_SOIL', 'CREA.G1.PERFOR.MODELLING.PINCH', 'Tries to model with dry soil.', '{"question":"What do you add to soil to model with it?","wrong_answer":"nothing","correct_answer":"water"}'::jsonb, 'The child has not felt how dry soil falls apart.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Try to make a ball from dry soil, then from wet soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION.M_CAC1_PC_SHAKE_DRUM', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'Says a drum is played by shaking.', '{"question":"How is a drum played?","wrong_answer":"by shaking it","correct_answer":"by hitting it"}'::jsonb, 'Shakers were shown first.', 'Offer "by shaking it" next to the right answer and ask the question again in a new context.', 'Shake a drum (no sound), then hit it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION.M_CAC1_PC_FLUTE', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'Calls a flute a percussion instrument.', '{"question":"Is a flute a percussion instrument?","wrong_answer":"yes","correct_answer":"no, you blow it"}'::jsonb, 'All instruments seem the same group.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Sort instruments: hit or shake, and blow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION.M_CAC1_PC_EMPTY_SHAKER', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'Makes a shaker with nothing inside.', '{"question":"What do you put inside a bottle to make a shaker?","wrong_answer":"nothing","correct_answer":"seeds or small stones"}'::jsonb, 'The child does not know what makes the sound.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Shake an empty bottle and a bottle of seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION.M_CAC1_PC_SCRAPE', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'Thinks scraping is not a way of playing.', '{"question":"Can an instrument be played by scraping?","wrong_answer":"no","correct_answer":"yes, like rubbing a stick along a ridged gourd"}'::jsonb, 'Hitting and shaking are better known.', 'Offer "no" next to the right answer and ask the question again in a new context.', 'Scrape a stick along a ridged bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES.M_CAC1_SS_HUMAN', 'CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'Says a person whistling is a bird.', '{"question":"Juma whistles a tune. What is the source of the sound?","wrong_answer":"a bird","correct_answer":"a person"}'::jsonb, 'Whistling sounds like a bird.', 'Offer "a bird" next to the right answer and ask the question again in a new context.', 'Whistle and then play a bird call.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES.M_CAC1_SS_OBJECT_ANIMAL', 'CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'Puts a car hooter with animal sounds.', '{"question":"Is a car hooter the sound of an animal or an object?","wrong_answer":"an animal","correct_answer":"an object"}'::jsonb, 'Loud sounds outside seem like animals.', 'Offer "an animal" next to the right answer and ask the question again in a new context.', 'Sort picture cards into animals, people and objects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES.M_CAC1_SS_RAIN', 'CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'Thinks rain on the roof is the roof making a sound by itself.', '{"question":"What makes the sound when it rains on the roof?","wrong_answer":"the roof by itself","correct_answer":"raindrops hitting the roof"}'::jsonb, 'The child hears the sound from the roof.', 'Offer "the roof by itself" next to the right answer and ask the question again in a new context.', 'Drop water on a tin and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES.M_CAC1_SS_ONE_SOURCE', 'CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'Names only one source in a busy place.', '{"question":"In a market, how many sources of sound can you hear?","wrong_answer":"one","correct_answer":"many: people, animals, vehicles, radios"}'::jsonb, 'The child attends to the loudest sound.', 'Offer "one" next to the right answer and ask the question again in a new context.', 'Close your eyes and count the sounds you hear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS.M_CAC1_ME_LOUD_HIGH', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'Calls a loud sound high.', '{"question":"A man sings a low note loudly. Is it high or low?","wrong_answer":"high, because it is loud","correct_answer":"low"}'::jsonb, 'In daily speech "high volume" and "high note" use the same word.', 'Offer "high, because it is loud" next to the right answer and ask the question again in a new context.', 'Sing a low note loudly and a high note softly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS.M_CAC1_ME_FAST_LOUD', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'Calls a fast song loud.', '{"question":"A song is sung quickly and softly. Is it loud?","wrong_answer":"yes, it is fast","correct_answer":"no, it is soft"}'::jsonb, 'Fast songs often feel loud.', 'Offer "yes, it is fast" next to the right answer and ask the question again in a new context.', 'Sing fast and soft, like a whisper race.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS.M_CAC1_ME_BIG_LOW', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'Thinks big animals make high sounds.', '{"question":"Which makes a lower sound: a cow or a chick?","wrong_answer":"a chick","correct_answer":"a cow"}'::jsonb, 'The child mixes up high and low.', 'Offer "a chick" next to the right answer and ask the question again in a new context.', 'Moo low and cheep high.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS.M_CAC1_ME_SLOW_SOFT', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MUSIC_ELEMENTS', 'Calls a slow song soft.', '{"question":"A song is slow and loud. Is it soft?","wrong_answer":"yes, because it is slow","correct_answer":"no, it is loud"}'::jsonb, 'Slow songs are often lullabies.', 'Offer "yes, because it is slow" next to the right answer and ask the question again in a new context.', 'Sing slowly but strongly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD.M_CAC1_MD_FAST_ANGRY', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'Says every fast song is angry.', '{"question":"A fast, bouncy song is about playing. What mood is it?","wrong_answer":"angry","correct_answer":"happy"}'::jsonb, 'Fast movement can look like anger to the child.', 'Offer "angry" next to the right answer and ask the question again in a new context.', 'Dance to the song: does it feel angry or happy?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD.M_CAC1_MD_WORDS_ONLY', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'Judges the mood only from one word.', '{"question":"A slow, soft song has the word \"sun\" in it. Is it exciting?","wrong_answer":"yes, the sun is fun","correct_answer":"no, it sounds calm"}'::jsonb, 'The child picks out one known word.', 'Offer "yes, the sun is fun" next to the right answer and ask the question again in a new context.', 'Listen with eyes closed: how does the music make you feel?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD.M_CAC1_MD_SLOW_SAD', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'Says every slow song is sad.', '{"question":"A slow, soft lullaby. Is it sad or calm?","wrong_answer":"sad","correct_answer":"calm"}'::jsonb, 'Slow and sad are linked for the child.', 'Offer "sad" next to the right answer and ask the question again in a new context.', 'Sing a lullaby to a baby doll and ask how it feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD.M_CAC1_MD_NO_REASON', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'Names a mood but cannot say why.', '{"question":"Why does this song sound happy?","wrong_answer":"because","correct_answer":"it is fast and bouncy"}'::jsonb, 'The child is not asked for reasons at home.', 'Offer "because" next to the right answer and ask the question again in a new context.', 'Ask: is it fast or slow? loud or soft?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME.M_CAC1_WH_BUCKET_SAFE', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'Thinks a bucket of water cannot be dangerous.', '{"question":"Can a baby be in danger near a bucket of water?","wrong_answer":"no, it is too small","correct_answer":"yes, a baby can fall in and drown"}'::jsonb, 'Danger is linked only with rivers and the sea.', 'Offer "no, it is too small" next to the right answer and ask the question again in a new context.', 'Talk about why a baby must never be left near a bucket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME.M_CAC1_WH_NOT_POINT', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'Thinks a jerrican or drum of water is not a water point.', '{"question":"Is a drum full of water at home a water point?","wrong_answer":"no, only rivers are","correct_answer":"yes"}'::jsonb, 'The child thinks water points are outside places.', 'Offer "no, only rivers are" next to the right answer and ask the question again in a new context.', 'Count all the places water is kept at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME.M_CAC1_WH_WET_FLOOR', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'Does not see a wet floor as a danger.', '{"question":"Water is spilt on the kitchen floor. What is the danger?","wrong_answer":"there is none","correct_answer":"someone can slip and fall"}'::jsonb, 'Spilt water seems harmless.', 'Offer "there is none" next to the right answer and ask the question again in a new context.', 'Walk carefully on a wet floor in role play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME.M_CAC1_WH_WELL_OPEN', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'Thinks an open well is safe if you can see the water.', '{"question":"Is an open well safe to play near?","wrong_answer":"yes, I can see the water","correct_answer":"no, a child can fall in"}'::jsonb, 'Seeing the water feels like being in control.', 'Offer "yes, I can see the water" next to the right answer and ask the question again in a new context.', 'Look at a picture of a covered and an open well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME.M_CAC1_WS_PLAY_ALONE', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'Thinks it is fine to play in a basin of water alone.', '{"question":"Can a small child play in water without an adult?","wrong_answer":"yes","correct_answer":"no, always with an adult near"}'::jsonb, 'Water play is fun and seems safe.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Role play asking an adult before water play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME.M_CAC1_WS_UNCOVERED', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'Leaves the lid off the water drum.', '{"question":"You take water from the drum. What do you do after?","wrong_answer":"leave the lid off","correct_answer":"put the lid back on"}'::jsonb, 'The child does not see a danger in an open drum.', 'Offer "leave the lid off" next to the right answer and ask the question again in a new context.', 'Ask: who could fall in or what could get in?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME.M_CAC1_WS_RUN', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'Runs on a wet floor.', '{"question":"The bathroom floor is wet. How do you walk?","wrong_answer":"run quickly","correct_answer":"walk slowly and carefully"}'::jsonb, 'Running feels quicker.', 'Offer "run quickly" next to the right answer and ask the question again in a new context.', 'Watch a toy slide on a wet tray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME.M_CAC1_WS_TELL', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'Does not tell an adult when a baby goes near water.', '{"question":"Your baby brother crawls to a basin of water. What do you do?","wrong_answer":"nothing","correct_answer":"call an adult at once"}'::jsonb, 'The child thinks the baby is only playing.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Role play calling an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
